// Distribution data — edit pct values to change splits.
window.BELLY_DATA = [
  { key: 'av', label: 'Avanzados',    pct: 50, color: '#dd3b2c', dark: '#7a1a13' },
  { key: 'in', label: 'Intermedios',  pct: 30, color: '#3a63f0', dark: '#16297d' },
  { key: 'pr', label: 'Principiantes', pct: 20, color: '#37bb66', dark: '#155a31' }
];

(function(){
  function build(){
    const host = document.getElementById('bellyChart');
    if (!host) return;
    const path = window.BELLY_PATH;
    const vbW = 100, vbH = window.BELLY_VBH;
    const data = window.BELLY_DATA;
    const total = data.reduce((a,b)=>a+b.pct,0) || 100;
    let y = 0;
    const bands = data.map((d) => {
      const h = (d.pct/total) * vbH;
      const band = { y, h, ...d };
      y += h;
      return band;
    });

    const defs = bands.map(b => `
      <linearGradient id="bgrad-${b.key}" x1="0%" y1="0%" x2="0%" y2="100%">
        <stop offset="0%" stop-color="${b.color}"/>
        <stop offset="100%" stop-color="${b.dark}"/>
      </linearGradient>`).join('');

    const rects = bands.map(b => `
      <rect class="bband band-${b.key}" x="0" y="${b.y.toFixed(3)}" width="${vbW}" height="${b.h.toFixed(3)}" fill="url(#bgrad-${b.key})"/>`).join('');

    // Divider lines between bands
    const lines = bands.slice(0,-1).map((b,i) => {
      const ly = (b.y + b.h).toFixed(3);
      return `<line class="bline bline-${i}" x1="0" y1="${ly}" x2="${vbW}" y2="${ly}" stroke="rgba(15,8,3,0.85)" stroke-width="0.45" vector-effect="non-scaling-stroke"/>`;
    }).join('');

    host.innerHTML = `
      <svg class="belly-svg" viewBox="0 0 ${vbW} ${vbH}" preserveAspectRatio="none" aria-hidden="true">
        <defs>
          ${defs}
          <clipPath id="belly-clip" clipPathUnits="userSpaceOnUse">
            <path d="${path}"/>
          </clipPath>
          <radialGradient id="belly-gloss" cx="50%" cy="32%" r="65%">
            <stop offset="0%" stop-color="rgba(255,255,255,0.42)"/>
            <stop offset="55%" stop-color="rgba(255,255,255,0.05)"/>
            <stop offset="100%" stop-color="rgba(0,0,0,0)"/>
          </radialGradient>
        </defs>
        <g clip-path="url(#belly-clip)">
          ${rects}
          ${lines}
          <rect x="0" y="0" width="${vbW}" height="${vbH}" fill="url(#belly-gloss)" style="mix-blend-mode:screen"/>
        </g>
        <path d="${path}" fill="none" stroke="rgba(15,8,3,0.78)" stroke-width="0.5" vector-effect="non-scaling-stroke"/>
      </svg>
      <div class="belly-labels">
        ${bands.map(b => {
          const cy = ((b.y + b.h/2) / vbH) * 100;
          return `<div class="blab blab-${b.key}" style="top:${cy.toFixed(2)}%">
            <b>${b.label}</b><span>${b.pct}%</span>
          </div>`;
        }).join('')}
      </div>`;
  }
  // Expose so the admin panel / prize-pool can re-render after edits
  window.renderBelly = build;
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', build);
  } else { build(); }
})();
